window.kbPageData["views/entry/k-b39cc1dc83e8f90b"] = {"key":"entry/k-b39cc1dc83e8f90b","state":{"route":"entry/k-b39cc1dc83e8f90b"},"node":{"id":"k-b39cc1dc83e8f90b","mode":"k","title":"《中华人民共和国生态环境法典》正式施行（8 月 15 日）","type":"事实与事件","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["ecology","law"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["生态环境"],"时间索引":["年度事件或数据"],"来源主题":["重要文件"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《中华人民共和国生态环境法典》正式施行（8 月 15 日）","slug":"da5473340d5f"}],"directorySummary":"考点二十 《中华人民共和国生态环境法典》正式施行（8 月 15 日）\n2026 年 8 月 15 日第四个全国生态日，《中华人民共和国生态环境法典》正式施行，标志着中\n国生态环境保护开启“法典化”时代。\n该法典于 2026 年 3 月 12 日由十四届全国人大四次会议表决通过，是继民法典后中国第二部…","sources":[{"id":"03c81608a13fe0a4","label":"《中华人民共和国生态环境法典》正式施行（8 月 15 日）","topic":"重要文件","category":"时政","text":"考点二十 《中华人民共和国生态环境法典》正式施行（8 月 15 日）\n2026 年 8 月 15 日第四个全国生态日，《中华人民共和国生态环境法典》正式施行，标志着中\n国生态环境保护开启“法典化”时代。\n该法典于 2026 年 3 月 12 日由十四届全国人大四次会议表决通过，是继民法典后中国第二部以\n“法典”命名的法律，也是世界上第一部以“生态环境”命名的法典，共 5 编、1242 条，是\n30 多部生态环境法律、100 余件行政法规、1000 多件地方性法规的“集大成者”。\n法典将“绿色低碳发展”独立成编，为世界范围内首次，标志着我国生态环境法治从“末端治\n污”转向“源头防控”；以“适度法典化”编纂模式形成法典统领、单行法配套衔接的分层立\n法格局。\n污染防治坚持精准治污、科学治污、依法治污方针；国家实行水资源刚性约束制度，坚持以水\n定城、以水定地、以水定人、以水定产。","source":{"doc":"4e539a366dce19555ccf","first":16,"last":16,"page":16,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"ecology","title":"生态保护与绿色转型"},{"slug":"law","title":"法治政府与依法行政"}],"units":{"k-b39cc1dc83e8f90b":[]}};
